fn is_decimal_with_two_precision(s: &[u8]) -> bool {
    // Check if the length of the slice is less than 3
    if s.len() < 3 {
        return false;
    }
    
    // Check if the character at position length - 3 is '.'
    let position = s.len() - 3;
    s[position] == b'.' && s.len() - position == 3
}

// Example usage
